-- Batch 11/12: Cardiac Emergencies MCQs 251-275
-- Focus: Special Populations, Rare Cardiac Emergencies, High-Yield Review
-- Sources: Tintinalli 9e, Case Files EM 5e, AHA Guidelines

DO $$
DECLARE
    tid UUID;
BEGIN
    SELECT id INTO tid FROM topics WHERE slug = 'em-cardiac-emergencies' LIMIT 1;
    IF tid IS NULL THEN RAISE EXCEPTION 'Topic not found'; END IF;


END $$;
